import sys
from collections import deque
from copy import deepcopy

# terrain: tuple of strings rows, '#' floor, '.' void, 'X' wall
# state: (terrain, player, goal, stars frozenset uncollected)
def parse(grid):
    g=[list(r) for r in grid]
    W=len(g[0]); H=len(g)
    player=goal=None; stars=set(); terr=[]
    for z,row in enumerate(g):
        r=[]
        for x,ch in enumerate(row):
            if ch in 'PG':
                r.append('#')
                if ch=='P': player=(x,z)
                else: goal=(x,z)
            elif ch=='S':
                r.append('#'); stars.add((x,z))
            else:
                r.append(ch)
        terr.append(r)
    return W,H,tuple(''.join(r) for r in terr),player,goal,frozenset(stars)

def walkable(terr,x,z):
    return 0<=z<len(terr) and 0<=x<len(terr[0]) and terr[z][x]!='.' and terr[z][x]!='X'

def reachable(terr,start):
    if not walkable(terr,*start): return frozenset()
    seen={start}; q=deque([start])
    while q:
        x,z=q.popleft()
        for dx,dz in ((1,0),(-1,0),(0,1),(0,-1)):
            n=(x+dx,z+dz)
            if n not in seen and walkable(terr,*n):
                seen.add(n); q.append(n)
    return frozenset(seen)

def apply_fold(state, axis, k, side):
    # side -1 = cells before k fold toward +; side +1 = cells >=k fold toward -
    terr,player,goal,uncollected=state
    H=len(terr); W=len(terr[0])
    grid=[list(r) for r in terr]
    # flap length check
    flap = k if side==-1 else W-k
    other = W-flap
    if flap<=0 or flap>other: return None
    new=[list(r) for r in terr]
    # clear folded side
    if axis=='v':
        if side==-1:
            for x in range(0,k):
                for z in range(H): new[z][x]='.'
        else:
            for x in range(k,W):
                for z in range(H): new[z][x]='.'
    else:
        if side==-1:
            for z in range(0,k):
                for x in range(W): new[z][x]='.'
        else:
            for z in range(k,H):
                for x in range(W): new[z][x]='.'
    def mirror(c):
        return 2*k-1-c
    def inside(x,z): return 0<=x<W and 0<=z<H
    # collect source items
    items=[]
    if axis=='v':
        xs=range(0,k) if side==-1 else range(k,W)
        for x in xs:
            for z in range(H):
                if grid[z][x]!='.':
                    items.append((x,z,grid[z][x],mirror(x),z))
    else:
        zs=range(0,k) if side==-1 else range(k,H)
        for z in zs:
            for x in range(W):
                if grid[z][x]!='.':
                    items.append((x,z,grid[z][x],x,mirror(z)))
    for sx,sz,ch,dx,dz in items:
        if not inside(dx,dz): return None
        # wall dominates
        if ch=='X' or new[dz][dx]=='X':
            new[dz][dx]='X'
        else:
            new[dz][dx]='#'
    terr2=tuple(''.join(r) for r in new)
    def mirror_pos(p):
        x,z=p
        if axis=='v': x=mirror(x)
        else: z=mirror(z)
        return (x,z)
    def on_flap(p):
        x,z=p
        if axis=='v': return (x<k) if side==-1 else (x>=k)
        return (z<k) if side==-1 else (z>=k)
    np=mirror_pos(player) if on_flap(player) else player
    ng=mirror_pos(goal) if on_flap(goal) else goal
    ns=set()
    for s in uncollected:
        ns.add(mirror_pos(s) if on_flap(s) else s)
    # invalid if player or goal ends up not floor
    if not walkable(terr2,*np): return None
    if not walkable(terr2,*ng): return 'goalfell'
    return (terr2,np,ng,frozenset(ns))

def collect(terr,uncollected,cell):
    if cell in uncollected:
        s=set(uncollected); s.remove(cell); return frozenset(s)
    return uncollected

def solve(grid, maxfolds=4, want_stars=False):
    W,H,terr,player,goal,stars=parse(grid)
    start=(terr,player,goal,stars)
    # BFS over states; fold count layers. Between folds player can move anywhere reachable.
    # collected stars when entering.
    seen=set(); q=deque()
    def key(st):
        return st
    # normalize: state after collecting reachable cells? We can collect only on cell entry but can move through; assume any reachable star can be collected.
    def collect_reachable(terr,uncollected,pos):
        r=reachable(terr,pos)
        return frozenset(s for s in uncollected if s not in r)
    uncol=collect_reachable(terr,stars,player)
    if want_stars and uncol: pass
    q.append((terr,player,goal,uncol,0,[]))
    seen.add((terr,player,goal,uncol))
    while q:
        terr,player,goal,uncol,fc,path=q.popleft()
        if player==goal and (not want_stars or not uncol):
            return path
        if fc>=maxfolds: continue
        area=reachable(terr,player)
        # choose any reachable cell as player pos at fold time
        for pos in area:
            for axis in ('v','h'):
                lim = W if axis=='v' else H
                for k in range(1,lim):
                    for side in (-1,1):
                        st=apply_fold((terr,pos,goal,uncol),axis,k,side)
                        if st in (None,'goalfell'): continue
                        t2,p2,g2,u2=st
                        if not walkable(t2,*p2) or not walkable(t2,*g2): continue
                        u2=collect_reachable(t2,u2,p2)
                        kk=(t2,p2,g2,u2)
                        if kk in seen: continue
                        seen.add(kk)
                        q.append((t2,p2,g2,u2,fc+1,path+[(axis,k,side,pos,p2)]))
    return None

if __name__=='__main__':
    grid=sys.argv[1:] if len(sys.argv)>1 else []
    if not grid:
        grid=[
        ".......",
        ".......",
        ".......",
        "#P#..#G",
        ".......",
        ".......",
        ".......",
        ]
    sol=solve(grid,5,False)
    print('\n'.join(grid))
    print('solution:',sol)

