  transition: background 180ms ease;
}
.switch span {
  display: block;
  width: 19px;
  height: 19px;
  margin: 0;
  border-radius: 50%;
  background: #fffdf7;
  box-shadow: 0 2px 4px rgba(50, 39, 22, 0.22);
  transition: transform 180ms ease;
}
.switch.on { background: var(--accent); }
.switch.on span { transform: translateX(21px); }
.segmented {
  display: flex;
  flex: 0 0 auto;
  padding: 3px;
  gap: 2px;
  border-radius: 10px;
  background: rgba(80, 63, 39, 0.09);
}
.segmented button {
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--ink-soft);
  padding: 7px 11px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  cursor: pointer;
}
.segmented button.active { background: #fffdf7; color: var(--ink); box-shadow: 0 2px 6px rgba(55, 42, 24, 0.12); }
.how-card {
  margin-top: 18px;
  padding: 16px;
  border-radius: 15px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.46), rgba(255, 255, 255, 0.12));
  border: 1px dashed rgba(95, 125, 79, 0.28);
}
.how-card h3 { margin: 0 0 12px; font-family: var(--font-display); font-size: 18px; font-weight: 500; }
.how-steps { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.how-steps > div { display: flex; gap: 8px; align-items: flex-start; }
.how-num {
  flex: 0 0 auto;
  width: 21px;
  height: 21px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--accent-deep);
  color: var(--paper);
  font-family: var(--font-display);
  font-size: 10px;
}
.how-steps p { margin: 0; font-size: 10px; line-height: 1.45; color: var(--ink-soft); }
.how-steps strong { color: var(--ink); }
.settings-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-top: 22px;
  padding-top: 14px;
  border-top: 1px solid rgba(95, 125, 79, 0.15);
}
.settings-foot p { margin: 0; font-size: 9px; letter-spacing: 0.14em; text-transform: uppercase; color: var(--ink-faint); }

/* ---------------- Game HUD ---------------- */
.screen-game { pointer-events: none; }
.screen-game.active { pointer-events: none; }
.hud {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: max(14px, env(safe-area-inset-top)) clamp(12px, 2.2vw, 24px) 0;
  z-index: 12;
}
.hud-left, .hud-right { display: flex; align-items: center; gap: 7px; pointer-events: auto; }
.hud-title {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  padding: 7px 12px;
  border-radius: 11px;
  background: rgba(250, 245, 233, 0.72);
  border: 1px solid rgba(255, 255, 255, 0.55);
  box-shadow: 0 8px 18px -16px rgba(57, 42, 23, 0.55);
  backdrop-filter: blur(8px);
}
.hud-title span { font-size: 8px; font-weight: 700; letter-spacing: 0.17em; text-transform: uppercase; color: var(--ink-faint); white-space: nowrap; }
.hud-title strong { font-family: var(--font-display); font-size: 15px; font-weight: 500; line-height: 1.1; letter-spacing: -0.015em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.icon-btn.glass {
  background: rgba(250, 245, 233, 0.74);
  border-color: rgba(255, 255, 255, 0.58);
  backdrop-filter: blur(8px);
}
.hud-stat {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 40px;
  padding: 0 10px;
  border-radius: 11px;
  background: rgba(250, 245, 233, 0.74);
  border: 1px solid rgba(255, 255, 255, 0.58);
  backdrop-filter: blur(8px);
  box-shadow: 0 8px 18px -16px rgba(57, 42, 23, 0.55);
  font-size: 12px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--ink-soft);
}
.hud-stat .icon { width: 15px; height: 15px; color: var(--accent); }
.hud-stat .icon.gold { color: var(--gold); }

#hint-card {
  position: fixed;
  left: 50%;
  bottom: calc(var(--safe-bottom) + 4px);
  transform: translateX(-50%);
  width: min(560px, calc(100vw - 20px));
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 10px 9px 12px;
  border-radius: 14px;
  background: rgba(250, 245, 233, 0.9);
  border: 1px solid rgba(255, 255, 255, 0.72);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.9) inset,
    0 14px 30px -20px rgba(54, 40, 22, 0.55);
  backdrop-filter: blur(9px);
  z-index: 13;
  pointer-events: auto;
}
.hint-badge {
  flex: 0 0 auto;
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: rgba(95, 125, 79, 0.14);
  color: var(--accent-deep);
}
.hint-badge .icon { width: 15px; height: 15px; }
#hint-text {
  flex: 1;
  margin: 0;
  font-size: 11.5px;
  line-height: 1.38;
  font-weight: 500;
  color: var(--ink-soft);
}
#btn-hint {
  flex: 0 0 auto;
  border: 1px solid rgba(95, 125, 79, 0.24);
  background: rgba(255, 255, 255, 0.4);
  color: var(--accent-deep);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  padding: 7px 9px;
  border-radius: 8px;
  cursor: pointer;
}
#btn-hint:hover { background: rgba(255, 255, 255, 0.8); }

#fold-meter {
  position: fixed;
  left: 50%;
  bottom: calc(var(--safe-bottom) + 74px);
  transform: translate(-50%, 6px);
  width: 244px;
  padding: 8px 11px 9px;
  border-radius: 12px;
  background: rgba(42, 34, 24, 0.76);
  color: var(--paper);
  box-shadow: 0 12px 30px -15px rgba(30, 22, 12, 0.7);
  backdrop-filter: blur(8px);
  opacity: 0;
  pointer-events: none;
  transition: opacity 150ms ease, transform 150ms ease;
  z-index: 14;
}
#fold-meter.show { opacity: 1; transform: translate(-50%, 0); }
.fold-meter-label { display: flex; align-items: center; gap: 6px; font-size: 9px; font-weight: 600; letter-spacing: 0.06em; text-transform: uppercase; opacity: 0.82; }
.fold-meter-label .icon { width: 12px; height: 12px; }
.fold-meter-track { margin-top: 6px; height: 3px; border-radius: 2px; background: rgba(255, 255, 255, 0.18); overflow: hidden; }
.fold-meter-track span { display: block; height: 100%; width: 0; background: linear-gradient(90deg, var(--gold-soft), var(--gold)); transition: width 60ms linear; }

#gesture-hint {
  position: fixed;
  left: 50%;
  top: 51%;
  transform: translate(-50%, -50%);
  display: none;
  align-items: center;
  gap: 9px;
  padding: 9px 14px 9px 10px;
  border-radius: 999px;
  background: rgba(45, 37, 26, 0.76);
  color: var(--paper);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.05em;
  backdrop-filter: blur(7px);
  box-shadow: 0 12px 30px -16px rgba(30, 22, 12, 0.7);
  pointer-events: none;
  z-index: 14;
  animation: hint-float 2.4s ease-in-out infinite;
}
#gesture-hint.show { display: flex; }
.swipe-line { width: 31px; height: 16px; color: var(--gold-soft); fill: currentColor; }
@keyframes hint-float { 0%,100% { transform: translate(-50%, -50%); } 50% { transform: translate(-50%, calc(-50% - 5px)); } }

#hurt-flash {
  position: fixed;
  inset: 0;
  z-index: 11;
  pointer-events: none;
  background: radial-gradient(80% 80% at 50% 50%, transparent 30%, rgba(122, 42, 26, 0.38) 100%);
  opacity: 0;
  transition: opacity 120ms ease;
}
#hurt-flash.on { opacity: 1; }

/* ---------------- Overlays ---------------- */
.overlay {
  position: fixed;
  inset: 0;
  z-index: 60;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 18px;
  background: rgba(33, 27, 19, 0.42);
  backdrop-filter: blur(8px);
  opacity: 0;
  visibility: hidden;
  transition: opacity 260ms ease, visibility 260ms;
}
.overlay.open { opacity: 1; visibility: visible; }
.modal-card {
  position: relative;
  width: min(480px, 96vw);
  max-height: 90vh;
  overflow: auto;
  padding: clamp(22px, 3.4vw, 34px);
  border-radius: 22px;
  border: 1px solid rgba(255, 255, 255, 0.72);
  background: linear-gradient(180deg, rgba(252, 247, 236, 0.99), rgba(242, 233, 214, 0.99));
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.9) inset,
    0 36px 80px -28px rgba(26, 19, 10, 0.65);
  text-align: center;
  transform: translateY(8px) scale(0.985);
  transition: transform 260ms ease;
}
.overlay.open .modal-card { transform: translateY(0) scale(1); }
.modal-card.small { width: min(370px, 96vw); }
.modal-card h2 { margin: 0 0 8px; }
.modal-copy { margin: 12px 0 22px; font-size: 11.5px; line-height: 1.55; color: var(--ink-soft); }
.modal-actions { display: flex; flex-direction: column; gap: 8px; margin-top: 20px; }
.modal-actions.row { flex-direction: row; flex-wrap: wrap; justify-content: center; }
.modal-actions.row .paper-btn { flex: 1; min-width: 110px; justify-content: center; }
.modal-actions .text-btn { align-self: center; }
.win-card { width: min(520px, 96vw); }
.win-stars { display: flex; justify-content: center; gap: clamp(10px, 3vw, 22px); margin: 24px 0 10px; }
.win-star { display: flex; flex-direction: column; align-items: center; gap: 5px; opacity: 0.32; }
.win-star svg { width: clamp(38px, 8vw, 52px); height: clamp(38px, 8vw, 52px); fill: var(--star-empty); filter: grayscale(1); transition: all 350ms ease; }
.win-star small { font-size: 8px; font-weight: 800; letter-spacing: 0.12em; text-transform: uppercase; color: var(--ink-faint); }
.win-star.earned { opacity: 1; }
.win-star.earned svg { fill: var(--gold); filter: drop-shadow(0 4px 8px rgba(168, 122, 38, 0.28)); animation: star-pop 520ms cubic-bezier(0.2, 1.5, 0.5, 1) both; }
.win-star.earned small { color: var(--ink-soft); }
@keyframes star-pop {
  0% { transform: scale(0.2) rotate(-35deg); opacity: 0; }
  70% { transform: scale(1.16) rotate(5deg); opacity: 1; }
  100% { transform: scale(1) rotate(0); opacity: 1; }
}
.win-stats { margin: 0; font-size: 10px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-faint); }
.win-quote { margin: 18px 0 0; font-family: var(--font-display); font-style: italic; font-size: 13px; line-height: 1.45; color: var(--ink-soft); }

/* ---------------- World intro / toast / veil ---------------- */
.world-card {
  position: fixed;
  left: 50%;
  top: 42%;
  transform: translate(-50%, -50%);
  width: min(520px, 88vw);
  padding: 22px 26px;
  text-align: center;
  z-index: 40;
  opacity: 0;
  pointer-events: none;
  transition: opacity 500ms ease, transform 500ms ease;
  color: var(--ink);
  text-shadow: 0 2px 16px rgba(255, 250, 238, 0.65);
}
.world-card.show { opacity: 1; transform: translate(-50%, -50%) scale(1); }
.world-card.on-dark { color: var(--paper); text-shadow: 0 2px 22px rgba(20, 14, 35, 0.8); }
.world-card span { font-size: 10px; font-weight: 800; letter-spacing: 0.28em; text-transform: uppercase; opacity: 0.66; }
.world-card h2 { margin: 6px 0 4px; font-family: var(--font-display); font-size: clamp(2.3rem, 5vw, 3.6rem); font-weight: 500; line-height: 0.95; letter-spacing: -0.04em; }
.world-card p { margin: 8px 0 0; font-family: var(--font-display); font-style: italic; font-size: 14px; opacity: 0.8; }

#toast {
  position: fixed;
  left: 50%;
  bottom: calc(var(--safe-bottom) + 86px);
  transform: translate(-50%, 8px);
  max-width: min(420px, calc(100vw - 30px));
  padding: 10px 16px;
  border-radius: 999px;
  background: rgba(42, 34, 24, 0.84);
  color: var(--paper);
  font-size: 11px;
  font-weight: 600;
  line-height: 1.3;
  text-align: center;
  letter-spacing: 0.015em;
  box-shadow: 0 14px 30px -16px rgba(30, 22, 12, 0.75);
  opacity: 0;
  pointer-events: none;
  transition: opacity 180ms ease, transform 180ms ease;
  z-index: 70;
  backdrop-filter: blur(7px);
}
#toast.show { opacity: 1; transform: translate(-50%, 0); }

#veil {
  position: fixed;
  inset: 0;
  z-index: 100;
  background: var(--paper);
  opacity: 0;
  pointer-events: none;
  transition: opacity 240ms ease;
}
#veil.on { opacity: 1; }

/* ---------------- Responsive ---------------- */
@media (max-width: 900px) {
  .skin-grid { grid-template-columns: repeat(2, 1fr); }
  .how-steps { grid-template-columns: 1fr; }
  .sheet { max-height: 92vh; }
}
@media (max-width: 760px) {
  .screen-menu::before {
    background:
      linear-gradient(180deg, rgba(246, 238, 219, 0.7) 0%, rgba(246, 238, 219, 0) 28%, rgba(246, 238, 219, 0) 52%, rgba(246, 238, 219, 0.88) 78%, rgba(246, 238, 219, 0.96) 100%);
  }
  .menu-main {
    justify-content: flex-end;
    align-items: center;
    text-align: center;
    padding-top: 0;
    padding-bottom: 8px;
    gap: 18px;
  }
  .title-lockup { max-width: 520px; }
  .eyebrow { justify-content: center; font-size: 9px; }
  .game-title { font-size: clamp(3.4rem, 15vw, 5.8rem); }
  .lede { font-size: 1rem; margin-top: 18px; }
  .menu-actions { width: min(330px, 86vw); }
  .menu-progress { justify-content: center; }
  .menu-foot { font-size: 9px; }
  .menu-foot-note { display: none; }
  .brand-word { display: none; }
  .level-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .sheet::after { margin: -20px -20px 0 0; }
  .hud { padding-left: 9px; padding-right: 9px; gap: 5px; }
  .hud-left, .hud-right { gap: 5px; }
  .icon-btn { width: 36px; height: 36px; border-radius: 10px; }
  .icon-btn .icon { width: 17px; height: 17px; }
  .hud-stat { height: 36px; padding: 0 8px; font-size: 11px; border-radius: 10px; }
  .hud-title { padding: 5px 8px; border-radius: 9px; max-width: 92px; }
  .hud-title span { display: none; }
  .hud-title strong { font-size: 12px; }
  #hint-card { border-radius: 12px; padding: 8px 8px 8px 10px; gap: 8px; }
  #hint-text { font-size: 10.5px; }
  #btn-hint { padding: 6px 7px; font-size: 8px; }
  #fold-meter { bottom: calc(var(--safe-bottom) + 66px); }
  .win-star small { font-size: 7px; }
}
@media (max-width: 420px) {
  .menu-row { gap: 6px; }
  .menu-row .paper-btn { padding: 12px 4px; font-size: 11px; }
  .game-title { font-size: clamp(3rem, 16vw, 4.8rem); }
  .menu-actions { width: min(320px, 92vw); }
  .level-grid { gap: 8px; }
  .level-card { padding: 8px; border-radius: 12px; }
  .level-card h4 { font-size: 11px; }
  .card-stars .icon { width: 9px; height: 9px; }
  .sheet { padding: 18px; border-radius: 20px; }
  .sheet-head { gap: 10px; }
  .settings-foot { flex-direction: column; align-items: flex-start; }
  .modal-actions.row .paper-btn { min-width: 90px; }
  .hud-stat .icon { width: 13px; height: 13px; }
  .hud-stat { padding: 0 6px; }
  #hint-text { font-size: 10px; }
  .hint-badge { width: 26px; height: 26px; }
}
@media (max-height: 560px) {
  .menu-main { gap: 12px; }
  .lede { display: none; }
  .game-title { font-size: clamp(2.6rem, 10vh, 4rem); }
  .menu-foot { display: none; }
  .eyebrow { display: none; }
  .paper-btn.primary { min-height: 52px; }
  .btn-label { font-size: 22px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
  }
}

