355: export function parseGrid(def) {
356:   const H = def.grid.length;
357:   const W = def.grid[0].length;
358:   const terrain = [];
359:   let player = null;
360:   let goal = null;
361:   const stars = new Set();
362: 
363:   for (let z = 0; z < H; z += 1) {
364:     const row = def.grid[z];
365:     if (row.length !== W) throw new Error(`Level ${def.id}: row ${z} is ${row.length} wide, expected ${W}`);
366:     const line = [];
367:     for (let x = 0; x < W; x += 1) {
368:       const ch = row[x];
369:       if (ch === '.') line.push(VOID);
370:       else if (ch === 'X') line.push(WALL);
371:       else {
372:         line.push(FLOOR);
373:         if (ch === 'P') player = { x, z };
374:         else if (ch === 'G') goal = { x, z };
375:         else if (ch === 'S') stars.add(key(x, z));
376:       }
377:     }
378:     terrain.push(line);
379:   }
380:   if (!player) throw new Error(`Level ${def.id}: no player start`);
381:   if (!goal) throw new Error(`Level ${def.id}: no goal`);
382: 
383:   const enemies = (def.enemies || []).map((enemy) => {
384:     const route = enemy.route
385:       .map(([x, z]) => ({ x, z }))
386:       .filter((cell) => cell.x >= 0 && cell.x < W && cell.z >= 0 && cell.z < H && terrain[cell.z][cell.x] === FLOOR);
387:     return {
388:       route,
389:       idx: 0,
390:       dir: 1,
391:       speed: enemy.speed || 1.2,
392:       timer: 0,
393:     };
394:   }).filter((enemy) => enemy.route.length >= 2);
395: 
396:   return { W, H, terrain, player, goal, stars, enemies };
397: }
