457: export function reachableCells(state, from = state.player) {
458:   const seen = new Set();
459:   if (!isWalkable(state, from.x, from.z)) return seen;
460:   const queue = [from];
461:   seen.add(key(from.x, from.z));
462:   for (let head = 0; head < queue.length; head += 1) {
463:     const cell = queue[head];
464:     for (const [dx, dz] of DIRS) {
465:       const nx = cell.x + dx;
466:       const nz = cell.z + dz;
467:       const k = key(nx, nz);
468:       if (!seen.has(k) && isWalkable(state, nx, nz)) {
469:         seen.add(k);
470:         queue.push({ x: nx, z: nz });
471:       }
472:     }
473:   }
474:   return seen;
475: }
