477: export function findPath(state, from, to) {
478:   if (!isWalkable(state, to.x, to.z)) return null;
479:   if (from.x === to.x && from.z === to.z) return [];
480:   const startKey = key(from.x, from.z);
481:   const targetKey = key(to.x, to.z);
482:   const parents = new Map([[startKey, null]]);
483:   const queue = [from];
484:   for (let head = 0; head < queue.length; head += 1) {
485:     const cell = queue[head];
486:     for (const [dx, dz] of DIRS) {
487:       const nx = cell.x + dx;
488:       const nz = cell.z + dz;
489:       const nk = key(nx, nz);
490:       if (parents.has(nk) || !isWalkable(state, nx, nz)) continue;
491:       parents.set(nk, cell);
492:       if (nk === targetKey) {
493:         const path = [];
494:         let cursor = { x: nx, z: nz };
495:         while (cursor) {
496:           path.push(cursor);
497:           const k = key(cursor.x, cursor.z);
498:           cursor = parents.get(k);
499:         }
500:         path.reverse();
501:         path.shift();
502:         return path;
503:       }
504:       queue.push({ x: nx, z: nz });
505:     }
506:   }
507:   return null;
508: }
