521: export function foldSides(state, axis, k) {
522:   if (axis === 'x') {
523:     const left = [];
524:     for (let x = 0; x < k; x += 1) for (let z = 0; z < state.H; z += 1) left.push({ x, z });
525:     const right = [];
526:     for (let x = k; x < state.W; x += 1) for (let z = 0; z < state.H; z += 1) right.push({ x, z });
527:     return { left, right };
528:   }
529:   const top = [];
530:   for (let z = 0; z < k; z += 1) for (let x = 0; x < state.W; x += 1) top.push({ x, z });
531:   const bottom = [];
532:   for (let z = k; z < state.H; z += 1) for (let x = 0; x < state.W; x += 1) bottom.push({ x, z });
533:   return { top, bottom };
534: }
