550: export function foldPlan(state, axis, k, side) {
551:   if (axis !== 'x' && axis !== 'z') return { ok: false, reason: 'bad-axis' };
552:   if (!Number.isInteger(k)) return { ok: false, reason: 'bad-crease' };
553:   const total = axis === 'x' ? state.W : state.H;
554:   if (k < 1 || k >= total) return { ok: false, reason: 'bad-crease' };
555:   const foldedLen = side < 0 ? k : total - k;
556:   const otherLen = total - foldedLen;
557:   if (foldedLen < 1) return { ok: false, reason: 'empty' };
558:   if (foldedLen > otherLen) return { ok: false, reason: 'too-wide' };
559: 
560:   const sides = foldSides(state, axis, k);
561:   const sources = side < 0 ? (axis === 'x' ? sides.left : sides.top) : (axis === 'x' ? sides.right : sides.bottom);
562:   let sourceTerrain = 0;
563:   for (const cell of sources) if (state.terrain[cell.z][cell.x] !== VOID) sourceTerrain += 1;
564:   if (sourceTerrain === 0) return { ok: false, reason: 'empty' };
565: 
566:   const next = cloneState(state);
567:   const grid = next.terrain;
568: 
569:   // clear the folded half; it is about to become the top layer
570:   for (const cell of sources) grid[cell.z][cell.x] = VOID;
571: 
572:   const mergeTerrain = (src, dst) => {
573:     if (src === VOID) return grid[dst.z][dst.x];
574:     if (grid[dst.z][dst.x] === WALL || src === WALL) return WALL;
575:     return FLOOR;
576:   };
577: 
578:   for (const cell of sources) {
579:     const dst = mirrorCell(cell, axis, k);
580:     if (!inBounds(next, dst.x, dst.z)) return { ok: false, reason: 'overhang' };
581:     grid[dst.z][dst.x] = mergeTerrain(state.terrain[cell.z][cell.x], dst);
582:   }
583: 
584:   const movePoint = (point) => (isOnFlap(point, axis, k, side) ? mirrorCell(point, axis, k) : { ...point });
585:   next.player = movePoint(next.player);
586:   next.goal = movePoint(next.goal);
587: 
588:   const movedStars = new Set();
589:   for (const starKey of next.stars) {
590:     const { x, z } = parseKey(starKey);
591:     const dst = isOnFlap({ x, z }, axis, k, side) ? mirrorCell({ x, z }, axis, k) : { x, z };
592:     if (inBounds(next, dst.x, dst.z)) movedStars.add(key(dst.x, dst.z));
593:   }
594:   next.stars = movedStars;
595: 
596:   // enemies are physical paper objects too; mirror their patrol route
597:   const nextEnemies = [];
598:   for (const enemy of next.enemies) {
599:     const current = enemyCell(enemy);
600:     const route = [];
601:     const seen = new Set();
602:     for (const cell of enemy.route) {
603:       const dst = isOnFlap(cell, axis, k, side) ? mirrorCell(cell, axis, k) : { ...cell };
604:       if (!inBounds(next, dst.x, dst.z) || next.terrain[dst.z][dst.x] !== FLOOR) continue;
605:       const kk = key(dst.x, dst.z);
606:       if (seen.has(kk)) continue;
607:       seen.add(kk);
608:       route.push(dst);
609:     }
610:     if (route.length < 2) continue;
611:     let idx = 0;
612:     if (current) {
613:       const mc = isOnFlap(current, axis, k, side) ? mirrorCell(current, axis, k) : current;
614:       const found = route.findIndex((cell) => cell.x === mc.x && cell.z === mc.z);
615:       if (found >= 0) idx = found;
616:     }
617:     nextEnemies.push({ ...enemy, route, idx, timer: 0 });
618:   }
619:   next.enemies = nextEnemies;
620: 
621:   if (!isWalkable(next, next.player.x, next.player.z)) {
622:     return { ok: false, reason: 'player-drops' };
623:   }
624:   if (!isWalkable(next, next.goal.x, next.goal.z)) {
625:     return { ok: false, reason: 'goal-drops' };
626:   }
627: 
628:   // the folded page lands as a new layer; a star beneath the player is picked up
629:   collectStar(next, next.player.x, next.player.z);
630: 
631:   next.folds = state.folds + 1;
632:   next.moves = state.moves;
633: 
634:   return {
635:     ok: true,
636:     state: next,
637:     sources,
638:     dst: mirrorCell(sources[0] || { x: 0, z: 0 }, axis, k),
639:     foldedLen,
640:     otherLen,
641:   };
642: }
