import { chromium } from 'playwright-core';
import fs from 'node:fs';

const url = 'http://127.0.0.1:3002/';
const shot = '/home/runner/work/PlayGround/PlayGround/screenshots/latest.jpg';
fs.mkdirSync('/home/runner/work/PlayGround/PlayGround/screenshots', { recursive: true });

const browser = await chromium.launch({
  executablePath: '/usr/bin/chromium',
  headless: true,
  args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist'],
});
const page = await browser.newPage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
const errors = [];
page.on('pageerror', (err) => errors.push(String(err?.stack || err)));
page.on('console', (msg) => { if (msg.type() === 'error') errors.push(msg.text()); });

await page.goto(url, { waitUntil: 'networkidle' });
await page.waitForTimeout(2600);

// open level 1
await page.click('#btn-play');
await page.waitForTimeout(1800);

const levelState1 = await page.evaluate(() => {
  const g = window.__lastFold;
  return {
    screen: g.screen, level: g.levelId, player: g.state.player, goal: g.state.goal,
    stars: [...g.state.stars], folds: g.state.folds, theme: g.theme.id,
    playerPos: { x: g.world.player.position.x, z: g.world.player.position.z },
    hint: document.querySelector('#hint-text')?.textContent,
    freeze: g.freezeUntil,
  };
});

const cellPoint = async (x, z) => page.evaluate(({ x, z }) => {
  const w = window.__lastFold.world;
  const v = w.camera.position.clone();
  v.set(w.worldX(x), 0.07, w.worldZ(z)).project(w.camera);
  return { x: (v.x * 0.5 + 0.5) * window.innerWidth, y: (-v.y * 0.5 + 0.5) * window.innerHeight };
}, { x, z });

const p = await cellPoint(levelState1.player.x, levelState1.player.z);
console.log('player screen point', p);

// swipe right across the gap
await page.mouse.move(p.x, p.y);
await page.mouse.down();
for (let i = 1; i <= 12; i += 1) {
  await page.mouse.move(p.x + i * 11, p.y);
  await page.waitForTimeout(16);
}
const mid = await page.evaluate(() => ({
  gesture: window.__lastFold.gesture ? {
    progress: window.__lastFold.gesture.progress,
    reason: window.__lastFold.gesture.reason,
    foldPlan: window.__lastFold.gesture.fold ? { axis: window.__lastFold.gesture.fold.axis, k: window.__lastFold.gesture.fold.k, side: window.__lastFold.gesture.fold.side } : null,
  } : null,
  meter: document.querySelector('#fold-meter')?.className,
}));
await page.screenshot({ path: shot, type: 'jpeg', quality: 76 });
await page.mouse.up();
await page.waitForTimeout(750);

const levelState2 = await page.evaluate(() => {
  const g = window.__lastFold;
  return {
    screen: g.screen, level: g.levelId, player: g.state.player, goal: g.state.goal,
    stars: [...g.state.stars], folds: g.state.folds, history: g.history.length,
    won: g.won, caught: g.caught, terrainRow: g.state.terrain[g.state.player.z].join(''),
    hud: { folds: document.querySelector('#hud-folds')?.textContent, stars: document.querySelector('#hud-stars')?.textContent },
  };
});

// tap goal
const gp = await cellPoint(levelState2.goal.x, levelState2.goal.z);
await page.mouse.click(gp.x, gp.y);
await page.waitForTimeout(1600);

const levelState3 = await page.evaluate(() => {
  const g = window.__lastFold;
  return {
    screen: g.screen, level: g.levelId, player: g.state.player, goal: g.state.goal,
    folds: g.state.folds, won: g.won, save: g.save.levels,
    winOpen: document.querySelector('#win-modal')?.classList.contains('open'),
    winStars: [...document.querySelectorAll('#win-stars .win-star')].map((e) => ({ k: e.dataset.star, earned: e.classList.contains('earned') })),
    winStats: document.querySelector('#win-stats')?.textContent,
  };
});

await page.screenshot({ path: shot, type: 'jpeg', quality: 76 });
console.log(JSON.stringify({ mid, levelState1, levelState2, levelState3, errors }, null, 2));
await browser.close();

