import { chromium } from 'playwright-core';
import fs from 'node:fs';

const url = 'http://127.0.0.1:3002/';
const dir = '/home/runner/work/PlayGround/PlayGround/screenshots';
fs.mkdirSync(dir, { recursive: true });

const browser = await chromium.launch({
  executablePath: '/usr/bin/chromium',
  headless: true,
  args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist'],
});

async function makePage(width, height) {
  const page = await browser.newPage({ viewport: { width, height }, deviceScaleFactor: 1 });
  page.errors = [];
  page.on('pageerror', (err) => page.errors.push(String(err?.stack || err)));
  page.on('console', (msg) => { if (msg.type() === 'error') page.errors.push(msg.text()); });
  await page.goto(url, { waitUntil: 'networkidle' });
  await page.waitForTimeout(2400);
  return page;
}

const desktop = await makePage(1280, 800);
await desktop.click('#btn-play');
await desktop.waitForTimeout(2600);
await desktop.screenshot({ path: `${dir}/latest.jpg`, type: 'jpeg', quality: 78 });

const layout = await desktop.evaluate(() => {
  const inspect = (sel) => {
    const el = document.querySelector(sel);
    if (!el) return null;
    const r = el.getBoundingClientRect();
    return { l: Math.round(r.left), t: Math.round(r.top), r: Math.round(r.right), b: Math.round(r.bottom), w: Math.round(r.width), h: Math.round(r.height), scrollW: el.scrollWidth, scrollH: el.scrollHeight };
  };
  return {
    hud: inspect('.hud'), left: inspect('.hud-left'), right: inspect('.hud-right'),
    title: inspect('.hud-title'), hint: inspect('#hint-card'), canvas: inspect('#scene'),
    body: { w: innerWidth, h: innerHeight, scrollW: document.body.scrollWidth, scrollH: document.body.scrollHeight },
    state: (() => { const g = window.__lastFold; return { screen: g.screen, level: g.levelId, player: g.state.player, folds: g.state.folds, quality: g.activeQuality }; })(),
  };
});
console.log('DESKTOP', JSON.stringify(layout, null, 2));
console.log('DESKTOP ERRORS', desktop.errors);

// go to level atlas, skins, settings and shoot each
await desktop.click('#btn-exit');
await desktop.waitForTimeout(650);
await desktop.screenshot({ path: `${dir}/latest.jpg`, type: 'jpeg', quality: 78 });
const levelCards = await desktop.evaluate(() => ({
  cards: document.querySelectorAll('.level-card').length,
  locked: document.querySelectorAll('.level-card.locked').length,
  sheet: (() => { const r = document.querySelector('#screen-levels .sheet')?.getBoundingClientRect(); return r ? { w: Math.round(r.width), h: Math.round(r.height), scrollH: document.querySelector('#screen-levels .sheet').scrollHeight } : null; })(),
}));
console.log('LEVELS', JSON.stringify(levelCards));

await desktop.evaluate(() => document.querySelector('[data-go="menu"]')?.click());
await desktop.waitForTimeout(550);
await desktop.click('#btn-skins');
await desktop.waitForTimeout(550);
await desktop.screenshot({ path: `${dir}/latest.jpg`, type: 'jpeg', quality: 78 });
const skins = await desktop.evaluate(() => ({
  cards: document.querySelectorAll('.skin-card').length,
  selected: document.querySelectorAll('.skin-card.selected').length,
  locked: document.querySelectorAll('.skin-card.locked').length,
}));
console.log('SKINS', JSON.stringify(skins));

await desktop.evaluate(() => document.querySelector('[data-go="menu"]')?.click());
await desktop.waitForTimeout(450);
await desktop.click('#btn-settings');
await desktop.waitForTimeout(550);
await desktop.screenshot({ path: `${dir}/latest.jpg`, type: 'jpeg', quality: 78 });
console.log('SETTINGS ERRORS', desktop.errors);

// mobile pass
const mobile = await makePage(390, 844);
