await mobile.click('#btn-play');
await mobile.waitForTimeout(2800);
await mobile.screenshot({ path: `${dir}/latest.jpg`, type: 'jpeg', quality: 78 });
const mobileGame = await mobile.evaluate(() => {
  const inspect = (sel) => {
    const el = document.querySelector(sel);
