import { LEVELS, createInitialState, foldPlan, reachableCells, key, findPath, isWalkable, collectStar } from './js/levels.js';
const paths = {
1:[['x',3,-1,{x:2,z:3}]],
2:[['z',4,1,{x:4,z:4}]],
3:[['x',3,-1,{x:3,z:3}]],
4:[['z',3,-1,{x:3,z:5}]],
5:[['x',2,-1,{x:2,z:6}]],
6:[['x',2,-1,{x:2,z:6}]],
7:[['x',3,-1,{x:1,z:1}],['z',3,-1,{x:4,z:1}]],
8:[['x',4,-1,{x:1,z:1}],['z',2,-1,{x:6,z:1}]],
9:[['x',2,-1,{x:6,z:1}],['z',2,-1,{x:6,z:1}]],
10:[['x',3,-1,{x:1,z:1}],['z',5,1,{x:4,z:1}]],
};
for (const def of LEVELS) {
  let state = createInitialState(def); state.enemies = [];
  let ok = true; let report=[];
  for (const [axis,k,side,from] of paths[def.id]) {
    // walk to from
    if (from.x!==state.player.x || from.z!==state.player.z) {
      const path = findPath(state, state.player, from);
      if (!path) { ok=false; report.push('cannot walk to fold start'); break; }
      state.player = from;
    }
    // collect every currently reachable star (walking)
    const reach = reachableCells(state);
    for (const s of [...state.stars]) if (reach.has(s)) { state.stars.delete(s); report.push('star '+s); }
    const res = foldPlan(state, axis,k,side);
    if (!res.ok) { ok=false; report.push('fold invalid '+res.reason); break; }
    state = res.state;
    if (res.collectedStar) report.push('star '+res.collectedStar);
    if (state.player.x===state.goal.x && state.player.z===state.goal.z && state.stars.size>0) {
      report.push('WARN landed on goal with '+state.stars.size+' stars left');
    }
  }
  if (ok) {
    const reach = reachableCells(state);
    for (const s of [...state.stars]) if (reach.has(s)) { state.stars.delete(s); report.push('star '+s); }
    const gp = findPath(state, state.player, state.goal);
    if (!gp) { ok=false; report.push('goal unreachable'); }
    else { state.player = state.goal; report.push('goal'); }
    if (state.stars.size) { ok=false; report.push('remaining stars '+[...state.stars]); }
  }
  console.log(`L${def.id} ${def.name}: ${ok?'OK':'CHECK'} | ${report.join(', ')}`);
}
EOF

