import { chromium } from 'playwright-core';
import fs from 'node:fs';

const URL = 'http://127.0.0.1:3002/';
const SHOTS = '/home/runner/work/PlayGround/PlayGround/screenshots';
fs.mkdirSync(SHOTS, { recursive: true });

const browser = await chromium.launch({
  executablePath: '/usr/bin/chromium',
  headless: true,
  args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist'],
});

const report = { checks: [], errors: [], consoleErrors: [], progress: [], skins: {}, reset: {}, enemy: {}, screens: {} };
const fail = (name, detail) => report.checks.push({ ok: false, name, detail });
const pass = (name, detail) => report.checks.push({ ok: true, name, detail });

function wire(page) {
  page.on('pageerror', (err) => report.errors.push(String(err?.stack || err)));
  page.on('console', (msg) => {
    if (msg.type() === 'error') report.consoleErrors.push(msg.text());
  });
}

async function boot(page) {
  await page.goto(URL, { waitUntil: 'networkidle' });
  await page.waitForFunction(() => Boolean(window.__lastFold) && document.body.dataset.ready === 'true', null, { timeout: 15000 });
  await page.waitForTimeout(1200);
}

const context = await browser.newContext({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
const page = await context.newPage();
wire(page);
await page.addInitScript(() => { try { localStorage.clear(); } catch { /* ignore */ } });
await boot(page);

const initial = await page.evaluate(() => {
  const g = window.__lastFold;
  return {
    screen: g.screen,
    totalStars: g.save ? null : null,
    save: g.save,
    menuChip: document.querySelector('#menu-progress-chip')?.textContent.trim(),
    cardCount: document.querySelectorAll('#level-worlds .level-card').length,
    lockedCards: document.querySelectorAll('#level-worlds .level-card.locked').length,
  };
});
initial.totalStars = await page.evaluate(() => window.__lastFold.updateMenuContent(), null);
initial.stars = await page.evaluate(() => {
  const g = window.__lastFold;
  return Object.values(g.save.levels).reduce((n, e) => n + (e.complete ? 1 : 0) + (e.golden ? 1 : 0) + (e.grace ? 1 : 0), 0);
});
report.screens.initial = initial;
if (initial.screen === 'menu') pass('boots to menu'); else fail('boots to menu', initial);
if (initial.stars === 0) pass('fresh save has 0 stars'); else fail('fresh save has 0 stars', initial.stars);
if (initial.lockedCards === 10) pass('all levels locked at start'); else fail('all levels locked at start', initial.lockedCards);

// Locked skin should not be selectable.
await page.evaluate(() => window.__lastFold.openSkins());
await page.waitForTimeout(120);
const skinLocks = await page.evaluate(() => ({
  cards: document.querySelectorAll('#skin-grid .skin-card').length,
  locked: document.querySelectorAll('#skin-grid .skin-card.locked').length,
  selected: document.querySelector('#skin-grid .skin-card.selected h4')?.textContent,
  toastBefore: document.querySelector('#toast')?.textContent,
}));
await page.locator('#skin-grid .skin-card').nth(1).click();
await page.waitForTimeout(200);
const lockedSkinResult = await page.evaluate(() => ({ skin: window.__lastFold.save.skin, toast: document.querySelector('#toast')?.textContent }));
report.skins.lockedAttempt = { ...skinLocks, ...lockedSkinResult };
if (skinLocks.cards === 4 && skinLocks.locked === 3 && skinLocks.selected === 'Ember Fox') pass('skin gallery shows 4 skins / 3 locked');
else fail('skin gallery shows 4 skins / 3 locked', skinLocks);
if (lockedSkinResult.skin === 'ember' && /Reach 6 stars/.test(lockedSkinResult.toast || '')) pass('locked skin rejected');
else fail('locked skin rejected', lockedSkinResult);

// Settings toggles.
await page.evaluate(() => window.__lastFold.openSettings(false));
await page.waitForTimeout(120);
await page.click('#set-sound');
const s1 = await page.evaluate(() => ({ sound: window.__lastFold.save.sound, stored: JSON.parse(localStorage.getItem('the-last-fold.save.v1')).sound, screen: window.__lastFold.screen }));
await page.click('#set-sound');
const s2 = await page.evaluate(() => window.__lastFold.save.sound);
await page.click('#set-motion');
const m1 = await page.evaluate(() => window.__lastFold.save.reducedMotion);
await page.click('#set-motion');
const m2 = await page.evaluate(() => window.__lastFold.save.reducedMotion);
await page.click('#set-quality button[data-quality="lite"]');
await page.waitForTimeout(150);
const q1 = await page.evaluate(() => ({ quality: window.__lastFold.save.quality, active: window.__lastFold.activeQuality, selected: document.querySelector('#set-quality button.active')?.dataset.quality, stored: JSON.parse(localStorage.getItem('the-last-fold.save.v1')).quality }));
await page.click('#set-quality button[data-quality="auto"]');
await page.waitForTimeout(120);
const q2 = await page.evaluate(() => ({ quality: window.__lastFold.save.quality, selected: document.querySelector('#set-quality button.active')?.dataset.quality }));
report.checks.push({ ok: s1.screen === 'settings' && s1.sound === false && s2 === true, name: 'sound toggle persists', detail: { s1, s2 } });
report.checks.push({ ok: m1 === true && m2 === false, name: 'motion toggle persists', detail: { m1, m2 } });
report.checks.push({ ok: q1.quality === 'lite' && q1.active === 'lite' && q1.selected === 'lite' && q1.stored === 'lite' && q2.quality === 'auto' && q2.selected === 'auto', name: 'quality selection applies', detail: { q1, q2 } });
await page.evaluate(() => window.__lastFold.leaveSettings());
await page.waitForTimeout(200);

// All ten levels: load each diorama, clear it at par with all stars, verify 3-star save/unlock flow.
for (let id = 1; id <= 10; id += 1) {
  const loaded = await page.evaluate((levelId) => {
    const g = window.__lastFold;
    g.startLevel(levelId, { intro: false, animateEntry: false });
    return {
      levelId: g.levelId,
      screen: g.screen,
      name: g.def?.name,
      par: g.def?.par,
      terrain: g.state?.terrain?.length,
      player: g.state?.player,
      goal: g.state?.goal,
      starsLeft: g.state?.stars?.size,
      enemies: g.state?.enemies?.length,
      hudWorld: document.querySelector('#hud-world')?.textContent,
      hudLevel: document.querySelector('#hud-level')?.textContent,
    };
  }, id);
  await page.waitForTimeout(160);
  const cleared = await page.evaluate((levelId) => {
    const g = window.__lastFold;
    g.state.stars.clear();
    g.state.folds = g.def.par;
    g.state.player = { ...g.state.goal };
    g.winLevel();
    const entry = g.save.levels[String(levelId)];
    const stars = Object.values(g.save.levels).reduce((n, e) => n + (e.complete ? 1 : 0) + (e.golden ? 1 : 0) + (e.grace ? 1 : 0), 0);
    const nextUnlocked = levelId < 10 ? Boolean(g.save.levels[String(levelId)]?.complete) : true;
    return { entry, stars, nextUnlocked, savedRaw: localStorage.getItem('the-last-fold.save.v1') !== null };
  }, id);
  report.progress.push({ id, ...loaded, ...cleared });
  const expectedStars = id * 3;
  const entryOk = cleared.entry?.complete && cleared.entry.bestStars === 3 && cleared.entry.bestFolds === loaded.par;
  const levelOk = loaded.levelId === id && loaded.screen === 'game' && loaded.terrain > 0 && loaded.hudLevel === loaded.name;
  report.checks.push({ ok: Boolean(levelOk), name: `level ${id} loads diorama`, detail: loaded });
  report.checks.push({ ok: Boolean(entryOk && cleared.stars === expectedStars && cleared.savedRaw), name: `level ${id} awards 3 stars + persists`, detail: { entry: cleared.entry, stars: cleared.stars } });
}

// Last-level win modal.
await page.waitForTimeout(750);
const winModal = await page.evaluate(() => ({
  open: document.querySelector('#win-modal')?.classList.contains('open'),
  title: document.querySelector('#win-title')?.textContent,
  stats: document.querySelector('#win-stats')?.textContent,
  earned: document.querySelectorAll('#win-stars .win-star.earned').length,
  next: document.querySelector('#btn-next')?.dataset.next,
}));
report.screens.win = winModal;
report.checks.push({ ok: winModal.open && winModal.title === 'The last fold.' && winModal.earned === 3 && winModal.next === '', name: 'final win modal shows 3 stars', detail: winModal });

// Level atlas fully unlocked and skins all available.
await page.evaluate(() => window.__lastFold.openLevels());
await page.waitForTimeout(180);
const atlas = await page.evaluate(() => ({
  screen: window.__lastFold.screen,
  cards: document.querySelectorAll('#level-worlds .level-card').length,
  completed: document.querySelectorAll('#level-worlds .level-card.completed').length,
  locked: document.querySelectorAll('#level-worlds .level-card.locked').length,
  chip: document.querySelector('#levels-star-chip')?.textContent.trim(),
  worldBlocks: document.querySelectorAll('#level-worlds .world-block').length,
}));
report.screens.atlas = atlas;
report.checks.push({ ok: atlas.cards === 10 && atlas.completed === 10 && atlas.locked === 0 && atlas.worldBlocks === 5 && /30\s*\/\s*30/.test(atlas.chip || ''), name: 'atlas shows 10 completed levels / 30 stars', detail: atlas });

await page.evaluate(() => window.__lastFold.openSkins());
await page.waitForTimeout(150);
const allSkins = await page.evaluate(() => ({ cards: document.querySelectorAll('#skin-grid .skin-card').length, locked: document.querySelectorAll('#skin-grid .skin-card.locked').length, selected: document.querySelector('#skin-grid .skin-card.selected h4')?.textContent }));
await page.locator('#skin-grid .skin-card').nth(3).click();
await page.waitForTimeout(180);
const koi = await page.evaluate(() => ({ skin: window.__lastFold.save.skin, selected: document.querySelector('#skin-grid .skin-card.selected h4')?.textContent, stored: JSON.parse(localStorage.getItem('the-last-fold.save.v1')).skin }));
await page.locator('#skin-grid .skin-card').nth(1).click();
await page.waitForTimeout(180);
const hare = await page.evaluate(() => ({ skin: window.__lastFold.save.skin, selected: document.querySelector('#skin-grid .skin-card.selected h4')?.textContent }));
report.skins.unlocked = { allSkins, koi, hare };
report.checks.push({ ok: allSkins.cards === 4 && allSkins.locked === 0 && koi.skin === 'koi' && koi.stored === 'koi' && hare.skin === 'snow', name: 'all skins unlock + selectable at 30 stars', detail: { allSkins, koi, hare } });

// Enemy collision resets the current page.
await page.evaluate(() => window.__lastFold.startLevel(6, { intro: false, animateEntry: false }));
await page.waitForTimeout(220);
const caught = await page.evaluate(() => {
  const g = window.__lastFold;
  const enemy = g.state.enemies[0];
  const cell = enemy.route[enemy.idx];
  g.state.player = { x: cell.x, z: cell.z };
  g.checkCollision();
  return {
    enemies: g.state.enemies.length,
    caught: g.caught,
    toast: document.querySelector('#toast')?.textContent,
    player: g.state.player,
    start: g.state.start,
    folds: g.state.folds,
  };
});
await page.waitForTimeout(1400);
const afterCaught = await page.evaluate(() => {
  const g = window.__lastFold;
  return { caught: g.caught, levelId: g.levelId, screen: g.screen, player: g.state?.player, start: g.state?.start, folds: g.state?.folds, toast: document.querySelector('#toast')?.textContent };
});
report.enemy = { caught, afterCaught };
report.checks.push({ ok: caught.enemies >= 1 && caught.caught === true && /ink shade caught you/.test(caught.toast || '') && afterCaught.caught === false && afterCaught.player?.x === afterCaught.start?.x && afterCaught.player?.z === afterCaught.start?.z && afterCaught.folds === 0, name: 'enemy collision resets page', detail: report.enemy });

// Reset flow from settings.
await page.evaluate(() => window.__lastFold.openSettings(false));
await page.waitForTimeout(120);
await page.click('#btn-reset');
await page.waitForTimeout(160);
const confirmOpen = await page.evaluate(() => document.querySelector('#confirm-modal')?.classList.contains('open'));
await page.click('#btn-confirm-reset');
await page.waitForTimeout(250);
const reset = await page.evaluate(() => {
  const g = window.__lastFold;
  const stored = JSON.parse(localStorage.getItem('the-last-fold.save.v1'));
  return {
    screen: g.screen,
    confirmOpen: document.querySelector('#confirm-modal')?.classList.contains('open'),
    save: g.save,
    stored,
    lockedSkins: document.querySelectorAll('#skin-grid .skin-card.locked').length,
    lockedLevels: document.querySelectorAll('#level-worlds .level-card.locked').length,
    menuChip: document.querySelector('#menu-progress-chip')?.textContent.trim(),
  };
});
report.reset = { confirmOpen, ...reset };
report.checks.push({ ok: confirmOpen && reset.screen === 'menu' && reset.save.skin === 'ember' && Object.keys(reset.save.levels).length === 0 && reset.save.sound === true && reset.save.quality === 'auto' && reset.save.reducedMotion === false && reset.stored.skin === 'ember' && /0\s*\/\s*30/.test(reset.menuChip || ''), name: 'reset progress restores defaults', detail: report.reset });

// Reload: reset state should persist.
await page.reload({ waitUntil: 'networkidle' });
await page.waitForFunction(() => Boolean(window.__lastFold) && document.body.dataset.ready === 'true', null, { timeout: 15000 });
await page.waitForTimeout(900);
const reloaded = await page.evaluate(() => ({ screen: window.__lastFold.screen, save: window.__lastFold.save, chip: document.querySelector('#menu-progress-chip')?.textContent.trim(), lockedSkins: document.querySelectorAll('#skin-grid .skin-card.locked').length }));
report.checks.push({ ok: reloaded.screen === 'menu' && Object.keys(reloaded.save.levels).length === 0 && reloaded.save.skin === 'ember' && /0\s*\/\s*30/.test(reloaded.chip || ''), name: 'reset persists after reload', detail: reloaded });

// Desktop screenshots.
await page.screenshot({ path: `${SHOTS}/selfcheck-desktop-menu.jpg`, type: 'jpeg', quality: 78 });
await page.evaluate(() => window.__lastFold.startLevel(1, { intro: false, animateEntry: false }));
await page.waitForTimeout(700);
await page.screenshot({ path: `${SHOTS}/selfcheck-desktop-game.jpg`, type: 'jpeg', quality: 78 });

// Mobile layout smoke + screenshots.
const mobile = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true });
const mp = await mobile.newPage();
wire(mp);
await mp.addInitScript(() => { try { localStorage.clear(); } catch { /* ignore */ } });
await boot(mp);
await mp.screenshot({ path: `${SHOTS}/selfcheck-mobile-menu.jpg`, type: 'jpeg', quality: 78 });
await mp.evaluate(() => window.__lastFold.startLevel(1, { intro: false, animateEntry: false }));
await mp.waitForTimeout(800);
await mp.evaluate(() => document.querySelector('#world-card')?.classList.remove('show'));
await mp.screenshot({ path: `${SHOTS}/latest.jpg`, type: 'jpeg', quality: 78 });
const mobileState = await mp.evaluate(() => ({
  screen: window.__lastFold.screen,
  level: window.__lastFold.levelId,
  scrollLocked: getComputedStyle(document.body).overflow,
  hudVisible: getComputedStyle(document.querySelector('#hud')).display,
  canvas: { w: document.querySelector('#scene')?.width, h: document.querySelector('#scene')?.height },
  controls: document.querySelector('#btn-pause')?.getBoundingClientRect().width,
  foldMeter: Boolean(document.querySelector('#fold-meter')),
  quality: window.__lastFold.activeQuality,
}));
report.screens.mobile = mobileState;
report.checks.push({ ok: mobileState.screen === 'game' && mobileState.level === 1 && mobileState.canvas.w > 0 && mobileState.controls > 20, name: 'mobile layout renders gameplay', detail: mobileState });

report.passCount = report.checks.filter((c) => c.ok).length;
report.failCount = report.checks.filter((c) => !c.ok).length;
console.log(JSON.stringify(report, null, 2));
await browser.close();

