import { chromium } from 'playwright-core';
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--use-gl=angle','--use-angle=swiftshader','--enable-webgl','--ignore-gpu-blocklist'] });
const page = await browser.newPage({ viewport: { width: 900, height: 700 } });
const errors=[]; page.on('pageerror',e=>errors.push(String(e)));
await page.goto('http://127.0.0.1:3002/', { waitUntil:'networkidle' });
await page.waitForFunction(()=>Boolean(window.__lastFold));
await page.waitForTimeout(900);
const before = await page.evaluate(()=>{ const g=window.__lastFold; const s=g.save; s.levels['1']={complete:true,golden:true,grace:true,bestFolds:1,bestStars:3}; s.levels['2']={complete:true,golden:true,grace:true,bestFolds:1,bestStars:3}; s.levels['3']={complete:true,golden:true,grace:true,bestFolds:1,bestStars:3}; s.levels['4']={complete:true,golden:true,grace:true,bestFolds:1,bestStars:3}; s.levels['5']={complete:true,golden:true,grace:true,bestFolds:1,bestStars:3}; g.persist(); g.startLevel(6,{intro:false,animateEntry:false}); return {idx:g.state.enemies[0].idx,dir:g.state.enemies[0].dir,route:g.state.enemies[0].route.length,player:g.state.player}; });
await page.waitForTimeout(2300);
const after = await page.evaluate(()=>{ const g=window.__lastFold; return {idx:g.state.enemies[0].idx,dir:g.state.enemies[0].dir,timer:g.state.enemies[0].timer,player:g.state.player,caught:g.caught,screen:g.screen}; });
console.log(JSON.stringify({before,after,errors},null,2));
await browser.close();
EOF
